/// <summary>
/// Provides a hook into the broadphase collision detection pipeline.
/// </summary>
/// <remarks>
/// Implement this interface to intercept shape pairs before narrowphase detection.
/// This can be used to filter out specific pairs, implement custom collision layers,
/// or handle collisions for custom proxy types. See <see cref="World.BroadPhaseFilter"/>.
/// </remarks>

translation:
/// <summary>
/// 提供接入宽相碰撞检测管线的钩子。
/// </summary>
/// <remarks>
/// 实现此接口可在窄相检测之前拦截形状对。
/// 可用于过滤特定形状对、实现自定义碰撞层，
/// 或为自定义代理类型处理碰撞。参见 <see cref="World.BroadPhaseFilter"/>。
/// </remarks>

source:
/// <summary>
/// Called for each pair of proxies whose bounding boxes overlap.
/// </summary>
/// <param name="proxyA">The first proxy.</param>
/// <param name="proxyB">The second proxy.</param>
/// <returns><c>true</c> to continue with narrowphase detection; <c>false</c> to skip this pair.</returns>

translation:
/// <summary>
/// 对每一对包围盒重叠的代理调用。
/// </summary>
/// <param name="proxyA">第一个代理。</param>
/// <param name="proxyB">第二个代理。</param>
/// <returns><c>true</c> 表示继续窄相检测；<c>false</c> 表示跳过此形状对。</returns>

source:
/// <summary>
/// Provides a hook into the narrowphase collision detection pipeline.
/// </summary>
/// <remarks>
/// Implement this interface to intercept collisions after contact generation.
/// This can be used to modify contact data, implement custom collision responses,
/// or filter out specific collisions.
/// </remarks>

translation:
/// <summary>
/// 提供接入窄相碰撞检测管线的钩子。
/// </summary>
/// <remarks>
/// 实现此接口可在接触生成之后拦截碰撞。
/// 可用于修改接触数据、实现自定义碰撞响应，
/// 或过滤掉特定碰撞。
/// </remarks>

source:
/// <summary>
/// Called for each detected collision with its contact data.
/// </summary>
/// <param name="shapeA">The first shape in the collision.</param>
/// <param name="shapeB">The second shape in the collision.</param>
/// <param name="pointA">Contact point on shape A (modifiable).</param>
/// <param name="pointB">Contact point on shape B (modifiable).</param>
/// <param name="normal">Collision normal used to solve the contact (modifiable). A positive normal
/// impulse pushes shape B along this direction and shape A against it.</param>
/// <param name="penetration">Signed penetration depth reported by the narrowphase. Changes to this value alone
/// do not affect the registered contact; its separation is derived from the contact points and normal.</param>
/// <returns><c>true</c> to keep the collision; <c>false</c> to discard it.</returns>

translation:
/// <summary>
/// 对每个检测到的碰撞及其接触数据调用。
/// </summary>
/// <param name="shapeA">碰撞中的第一个形状。</param>
/// <param name="shapeB">碰撞中的第二个形状。</param>
/// <param name="pointA">形状 A 上的接触点（可修改）。</param>
/// <param name="pointB">形状 B 上的接触点（可修改）。</param>
/// <param name="normal">用于求解接触的碰撞法线（可修改）。正的法线
/// 冲量会将形状 B 沿此方向推开，并将形状 A 反向推开。</param>
/// <param name="penetration">窄相报告的带符号穿透深度。仅修改此值
/// 不会影响已注册的接触；其分离量由接触点和法线推导得出。</param>
/// <returns><c>true</c> 表示保留该碰撞；<c>false</c> 表示丢弃该碰撞。</returns>

source:
/// <summary>
/// Filters internal edge collisions for <see cref="TriangleShape"/> geometry. Adjusts collision
/// normals at shared edges to match neighboring triangles, or discards the collision if the normal
/// cannot be resolved. Requires triangle adjacency information; boundary edges (no neighbor)
/// are left unmodified. Back-face normals within <see cref="AngleThreshold"/> of the opposite
/// triangle normal are discarded.
/// </summary>

translation:
/// <summary>
/// 过滤 <see cref="TriangleShape"/> 几何体的内部边碰撞。在共享边处调整碰撞
/// 法线以匹配相邻三角形，或在法线无法解析时丢弃该碰撞。需要三角形邻接信息；
/// 边界边（无邻接三角形）保持不变。与相对三角形法线夹角在
/// <see cref="AngleThreshold"/> 以内的背面法线会被丢弃。
/// </summary>

source:
/// <summary>
/// Gets or sets the distance threshold for edge collision detection, in world units.
/// </summary>
/// <remarks>
/// Larger values are more aggressive at filtering edges but may incorrectly affect
/// legitimate collisions near triangle boundaries.
/// </remarks>
/// <value>The default value is 0.01 world units.</value>

translation:
/// <summary>
/// 获取或设置边碰撞检测的距离阈值，单位为世界单位。
/// </summary>
/// <remarks>
/// 值越大，对边的过滤越激进，但可能错误地影响
/// 三角形边界附近的合法碰撞。
/// </remarks>
/// <value>默认值为 0.01 个世界单位。</value>

source:
/// <summary>
/// Gets or sets whether dynamic triangle bodies receive edge filtering. Static and kinematic
/// triangle geometry is always filtered. Defaults to <see langword="false"/>.
/// </summary>

translation:
/// <summary>
/// 获取或设置动态三角形刚体是否接受边过滤。静态和运动学
/// 三角形几何体始终会被过滤。默认为 <see langword="false"/>。
/// </summary>

source:
/// <summary>
/// Gets or sets the minimum length of the projected collision normal required to keep the contact.
/// </summary>
/// <remarks>
/// When the collision normal is projected onto the plane formed by the triangle normal and its
/// neighbor's normal, a very short projection indicates the collision is occurring along the
/// edge crease itself and is discarded. Lower values allow more edge collisions through;
/// higher values are more aggressive at filtering.
/// </remarks>
/// <value>The default value is 0.5.</value>

translation:
/// <summary>
/// 获取或设置保留接触所需的投影碰撞法线最小长度。
/// </summary>
/// <remarks>
/// 当碰撞法线投影到由三角形法线及其相邻三角形法线构成的平面上时，
/// 投影非常短意味着碰撞正沿边折痕本身发生，此时将丢弃该碰撞。
/// 值越小，允许通过的边碰撞越多；值越大，过滤越激进。
/// </remarks>
/// <value>默认值为 0.5。</value>

source:
/// <summary>
/// Gets or sets the angle threshold used for two purposes: determining when two triangle normals
/// are considered coplanar (using simpler snapping logic), and discarding back-face collisions
/// whose normal is anti-parallel to the triangle normal within this angle.
/// </summary>
/// <value>The default value is approximately 2.5 degrees.</value>

translation:
/// <summary>
/// 获取或设置用于两个目的的角度阈值：判断两个三角形法线
/// 何时被视为共面（使用更简单的吸附逻辑），以及丢弃法线在此角度内
/// 与三角形法线反平行的背面碰撞。
/// </summary>
/// <value>默认值约为 2.5 度。</value>

source:
// Check collision again (for non-speculative contacts),
// but with zero epa threshold parameter. This is necessary since
// MPR is not exact for flat shapes, like triangles.

translation:
// 再次检查碰撞（针对非推测接触），
// 但将 EPA 阈值参数设为零。这是必要的，因为
// MPR 对平面形状（如三角形）并不精确。

source:
// Now the fun part.
//
// we have a collision close to an edge, with
//
// triangleNormal -> the triangle normal where collision occurred
// neighborNormal -> the normal of the neighboring triangle
// normal         -> the collision normal

translation:
// 现在是有趣的部分。
//
// 我们在一条边附近发生了碰撞，其中
//
// triangleNormal -> 碰撞发生处的三角形法线
// neighborNormal -> 相邻三角形的法线
// normal         -> 碰撞法线

