/// via <see cref="GetLock"/> before calling <see cref="Add"/>, <see cref="Remove"/>,
/// <see cref="TryGetValue"/>, or the indexer during concurrent writes. <see cref="TrimExcess"/>
/// requires excluding all concurrent operations.
/// </para>
/// </remarks>

