/// <summary>
/// 一个分片字典，其条目被分区以减少锁争用。
/// 每个分片都有自己的锁，允许调用方独立同步不同分片。
/// </summary>
/// <typeparam name="TKey">字典中键的类型。</typeparam>
/// <typeparam name="TValue">字典中值的类型。</typeparam>
/// <remarks>
/// <para>
/// 此实现避免了 <see cref="System.Collections.Concurrent.ConcurrentDictionary{TKey,TValue}"/> 的 GC 开销。
