/// <b>线程：</b>单个操作不是线程安全的。在并发写入期间，调用方必须先通过
/// <see cref="GetLock"/> 获取分片锁，然后再调用 <see cref="Add"/>、<see cref="Remove"/>、
/// <see cref="TryGetValue"/> 或索引器。<see cref="TrimExcess"/>
/// 要求排除所有并发操作。
/// </para>
/// </remarks>

