/// <remarks>
/// 此事件提供一个 <see cref="Arbiter"/> 对象，其中包含已结束碰撞的详细信息。
/// 显式移除仲裁器、刚体或形状不会触发此事件。
/// </remarks>

source:
/// <summary>
/// Contains all bodies this body is in contact with or shares a constraint with.
/// </summary>

translation:
/// <summary>
/// 包含此刚体接触到的或与之共享约束的所有刚体。
/// </summary>

